    public static function svg(string $name, string $style = ''): string
    {
        if (!isset(self::$icons[$name])) {
            return '';
        }
        return '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="' . $style . '">'
            . self::$icons[$name]
            . '</svg>';
    }
